 private static final int INK=0xff141414,MUTED=0xff606460,GROUND=0xfff4f3f1,BLUE=0xff1d5fbf;
 private LinearLayout root,body,bottomRows,railRows;private TextView cityLabel,status,summary,railStatus;private RailEstimator.Result railEstimate;private EditText stopInput,lineInput;private Button start;private OsmMapView map;private android.graphics.Typeface face;private boolean compact,resumed,destroyed,tracking,refreshing,fitNext;private int city=0,screen=0,generation;private Handler handler=new Handler();private Thread request;private JourneyData.Snapshot snapshot;private ArrayList<JourneyData.RailLine> rails=new ArrayList<JourneyData.RailLine>();private JourneyData.RailLine selectedRail;
